BINARY_FILES = json.loads('{"assets/coin.png": "", "assets/crown.png": "", "assets/logo-b-glow.png": "", "assets/logo-b-plain.png": ""}')
root = "Brisic-Prototype"
for name, text in TEXT_FILES.items():
    p = os.path.join(root, name); os.makedirs(os.path.dirname(p), exist_ok=True)
    open(p, "w", encoding="utf-8", newline="").write(text)
for name, b64 in BINARY_FILES.items():
    p = os.path.join(root, name); os.makedirs(os.path.dirname(p), exist_ok=True)
    open(p, "wb").write(base64.b64decode(b64))
print("Done. Wrote", len(TEXT_FILES) + len(BINARY_FILES), "files into", root)
print("Next: cd Brisic-Prototype && python3 -m http.server 8000  then open http://localhost:8000/Splash.dc.html")
